transforms.result:
.homepage-manager {
  width: 100%;
}

.tab-content {
  padding: 0;
}

.content-header {
  margin-bottom: 2rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 500;
  color: #1A1A1A;
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.section-description {
  color: #666666;
  margin: 0;
}

.current-background {
  margin-bottom: 1.5rem;
}

.background-preview {
  position: relative;
  width: 100%;
  height: 200px;
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 1rem;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.preview-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s;
}

.background-preview:hover .preview-overlay {
  opacity: 1;
}

.background-info h4 {
  color: #1A1A1A;
  margin-bottom: 0.5rem;
}

.background-info p {
  color: #666666;
  margin: 0;
}

.preset-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 1rem;
}

.preset-item {
  position: relative;
  height: 80px;
  border-radius: 8px;
  overflow: hidden;
  cursor: pointer;
  border: 2px solid transparent;
  transition: all 0.3s;
}

.preset-item:hover {
  border-color: #667eea;
}

.preset-item.active {
  border-color: #667eea;
}

.preset-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.preset-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(102, 126, 234, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s;
}

.preset-item.active .preset-overlay {
  opacity: 1;
}

.button-settings h4 {
  color: #1A1A1A;
  font-weight: 500;
}

.partners-grid {
  display: grid;
  gap: 1rem;
}

.partner-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid #E0E0E0;
  border-radius: 8px;
}

.partner-logo {
  width: 60px;
  height: 60px;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
}

.partner-logo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.partner-info {
  flex: 1;
}

.partner-info h4 {
  color: #1A1A1A;
  margin-bottom: 0.25rem;
}

.partner-info p {
  color: #666666;
  margin-bottom: 0.25rem;
}

.partner-link {
  color: #667eea;
  text-decoration: none;
  font-size: 0.875rem;
}

.partner-actions {
  display: flex;
  gap: 0.25rem;
}

.empty-state {
  text-align: center;
  padding: 3rem;
  color: #666666;
}

.empty-state h3 {
  margin: 1rem 0 0.5rem;
}

.logo-preview {
  margin-top: 1rem;
  text-align: center;
}

.preview-logo {
  max-width: 150px;
  max-height: 100px;
  border-radius: 8px;
  border: 1px solid #E0E0E0;
}

/* 响应式设计 */
@media (max-width: 768px) {
  .preset-grid {
    grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
  }

  .preset-item {
    height: 60px;
  }

  .partner-item {
    flex-direction: column;
    align-items: flex-start;
  }

  .partner-logo {
    width: 80px;
    height: 80px;
  }
}

